// Des: Tests for nt-vend-live: transport on loopback, timeout, key files
// Flo: mock server > GET and POST through Live > timeout > key file load and redaction
// I/O: loopback replies, temp key files > pass or fail (no leaks)
// Run: zig build test
// ===================================================================
const std = @import("std"); const live = @import("nt-vend-live.zig"); const base = @import("nt-vend-base.zig"); const mock = @import("te-mock-serv.zig");
const allo = std.testing.allocator;
test "GET and POST go through, auth and JSON body arrive, key stays out of our output" { var srv: mock.Mock = undefined; try srv.start(std.testing.io); defer srv.halt(); var lv: live.Live = .{ .time_mill = 5000 }; const snd = lv.send(); var buf: [64]u8 = undefined; const one = try snd.call(snd.ctx, allo, std.testing.io, .{ .post = false, .urlz = srv.urlOf(&buf, "/ok") }); defer allo.free(one.body); try std.testing.expectEqual(@as(u16, 200), one.code); try std.testing.expectEqualStrings("<html>hello</html>", one.body); const two = try snd.call(snd.ctx, allo, std.testing.io, .{ .post = true, .urlz = srv.urlOf(&buf, "/vecho"), .auth = "Bearer SECRETKEY", .ctyp = "application/json", .body = "{\"url\":\"https://a.com/\"}" }); defer allo.free(two.body); try std.testing.expect(std.mem.indexOf(u8, two.body, "vendor echo page text") != null); try std.testing.expect(std.ascii.findIgnoreCase(srv.hdrLast(), "authorization: Bearer SECRETKEY") != null); try std.testing.expect(std.mem.indexOf(u8, srv.hdrLast(), "{\"url\":\"https://a.com/\"}") != null); }
test "vendor that hangs times out and the worker cleans up" { var srv: mock.Mock = undefined; try srv.start(std.testing.io); defer srv.halt(); var lv: live.Live = .{ .time_mill = 500 }; const snd = lv.send(); var buf: [64]u8 = undefined; try std.testing.expectError(error.Timeout, snd.call(snd.ctx, allo, std.testing.io, .{ .post = false, .urlz = srv.urlOf(&buf, "/hang") })); std.Io.sleep(std.testing.io, .fromMilliseconds(3600), .awake) catch {}; }
test "key file: first line trimmed, missing or empty = NoKey" { var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const dirz = try std.fmt.allocPrint(aren.allocator(), ".zig-cache/tmp/{s}", .{tmpz.sub_path}); try tmpz.dir.writeFile(std.testing.io, .{ .sub_path = "zenr.key", .data = "  abc123KEY \r\nsecond line\n" }); try tmpz.dir.writeFile(std.testing.io, .{ .sub_path = "deco.key", .data = "  \n" }); var rea: live.Real = .{ .gpaz = allo, .conf = .{}, .keyd = dirz }; try std.testing.expectEqualStrings("abc123KEY", try rea.keyLoad(aren.allocator(), std.testing.io, .zenr)); try std.testing.expectError(error.NoKey, rea.keyLoad(aren.allocator(), std.testing.io, .deco)); try std.testing.expectError(error.NoKey, rea.keyLoad(aren.allocator(), std.testing.io, .brig)); }
test "Real backend without a key file fails typed, before any network" { var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const dirz = try std.fmt.allocPrint(aren.allocator(), ".zig-cache/tmp/{s}", .{tmpz.sub_path}); var rea: live.Real = .{ .gpaz = allo, .conf = .{}, .keyd = dirz }; const bck = rea.backend(); try std.testing.expectError(error.NoKey, bck.call(bck.ctx, aren.allocator(), std.testing.io, .zenr, .{ .urlz = "https://a.com/", .mode = .plain })); }
